/** Error codes shared by every module (common.json "errors"). */
export const commonErrors = {
  "VALIDATION_FAILED": {
    "status": 400,
    "meaning": "Fields are missing or invalid. details.issues lists each field."
  },
  "UNAUTHORIZED": {
    "status": 401,
    "meaning": "No token, or the token is invalid, expired or revoked (details.reason token_*), or this session can't use the endpoint (details.reason, e.g. sign_in_required, session_idle). Refresh only when details.reason starts with token_."
  },
  "FORBIDDEN": {
    "status": 403,
    "meaning": "Signed in, but the role or seller permission does not allow this. details.permission names it; other refusals give details.reason."
  },
  "NOT_FOUND": {
    "status": 404,
    "meaning": "The record does not exist or is not visible to this caller."
  },
  "ILLEGAL_TRANSITION": {
    "status": 409,
    "meaning": "The status does not allow this action (e.g. approving a rejected product). details.from, details.event."
  },
  "APPROVAL_REQUIRED": {
    "status": 409,
    "meaning": "Above the caller's limit or needs a second reviewer, and nothing was saved (the action cannot be recorded until it is approved). details.approvalRequestId tracks it. When the module saves the record pending approval it answers its normal success status instead, with `approval` (ApprovalInfo) in the body (FORMAT.md, Approval responses)."
  },
  "CONFLICT": {
    "status": 409,
    "meaning": "Concurrent change; reload and retry."
  },
  "IDEMPOTENCY_KEY_REUSED": {
    "status": 422,
    "meaning": "The Idempotency-Key was used with a different request (path, query or body)."
  },
  "RATE_LIMITED": {
    "status": 429,
    "meaning": "Too many requests; retry after the Retry-After header (seconds, also in details.retryAfterSeconds)."
  },
  "NOT_IMPLEMENTED": {
    "status": 501,
    "meaning": "Designed but not built yet, or planned for a later launch phase (details.reason not_built or later_phase)."
  },
  "INTERNAL_ERROR": {
    "status": 500,
    "meaning": "Something went wrong on the server, or a response did not match the spec. Include the X-Request-Id when reporting it."
  },
  "RANGE_NOT_SATISFIABLE": {
    "status": 416,
    "meaning": "File downloads (GET /files/…): the requested Range is outside the file. details.sizeBytes."
  },
  "WRONG_AUDIENCE": {
    "status": 403,
    "meaning": "The token is for another app (store, Seller Center or Admin Center)."
  },
  "STEP_UP_REQUIRED": {
    "status": 403,
    "meaning": "A fresh proof is needed: a re-auth token for this purpose in the body (reauthToken, from the app's re-auth endpoint). details.kind (reauth), details.purpose."
  },
  "OWNER_ONLY": {
    "status": 403,
    "meaning": "Only the seller owner can do this."
  },
  "NO_SELLER_ACCESS": {
    "status": 403,
    "meaning": "This account cannot act for that seller (or for any seller)."
  },
  "UPGRADE_REQUIRED": {
    "status": 426,
    "meaning": "This Android app version is no longer supported; update the app. details.minVersionCode, details.updateUrl."
  },
  "SERVICE_UNAVAILABLE": {
    "status": 503,
    "meaning": "A service needed to authorize the request is unavailable; retry later."
  },
  "SERVICE_BUSY": {
    "status": 503,
    "meaning": "The rows this request needs were contended and it was retried as far as it can be; send it again. Retry-After says how long to wait. (docs/10-mysql-migration.md D8)"
  }
} as const;

